    int x_;
    int y_;
};

bool en_eje_vertical(const Punto& punto) {
    return punto.x() == 0;
}

int main() {
    Punto punto{0, 6};
    bool primero = en_eje_vertical(punto);
    punto.mover_a(2, 6);
    std::cout << primero << " " << en_eje_vertical(punto);
